import{_ as a}from"./chunks/page-dock.BwiiXitq.js";import{_ as r,o as d,c as e,a2 as o}from"./chunks/framework.CfwCq2QB.js";const i="/dev-go-docs/shots/0.2.3/zh-CN/dark/page-dock.png",m=JSON.parse('{"title":"悬浮快捷栏","description":"","frontmatter":{},"headers":[],"relativePath":"features/dock.md","filePath":"features/dock.md"}'),l={name:"features/dock.md"};function h(s,t,n,c,_,p){return d(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="悬浮快捷栏" tabindex="-1">悬浮快捷栏 <a class="header-anchor" href="#悬浮快捷栏" aria-label="Permalink to &quot;悬浮快捷栏&quot;">​</a></h1><p>一句话：网页右侧的深色悬浮条，悬停展开快捷操作——翻译本页 / 显示原文、AI 总结本页、AI 助手、回到顶部、设置；可以上下拖动，也可以按需关闭。</p><h2 id="形态" tabindex="-1">形态 <a class="header-anchor" href="#形态" aria-label="Permalink to &quot;形态&quot;">​</a></h2><ul><li><strong>收起</strong>：贴在网页右侧边缘的一根深色细条，中间有呼吸微光，几乎不占地方</li><li><strong>靠近</strong>：指针靠近时细条微微吸出，提示这里可以展开</li><li><strong>悬停展开</strong>：沿弹簧曲线展开成一列按钮，指针移开后折回细条</li><li>开了系统「减少动态效果」时自动关闭动画</li></ul><h2 id="按钮清单" tabindex="-1">按钮清单 <a class="header-anchor" href="#按钮清单" aria-label="Permalink to &quot;按钮清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>按钮</th><th>作用</th></tr></thead><tbody><tr><td>翻译本页 / 显示原文</td><td>切换整页双语翻译，翻译开启时按钮高亮</td></tr><tr><td>AI 总结本页</td><td>打开侧边栏并自动开始总结当前页</td></tr><tr><td>AI 助手</td><td>打开侧边栏对话</td></tr><tr><td>回到顶部</td><td>页面滚过一段距离后才出现</td></tr><tr><td>设置</td><td>打开设置页</td></tr></tbody></table><img src="'+a+'" alt="悬浮快捷栏展开"><h2 id="拖动" tabindex="-1">拖动 <a class="header-anchor" href="#拖动" aria-label="Permalink to &quot;拖动&quot;">​</a></h2><p>按住悬浮条可以上下拖动，松手后记住位置。拖到页面底部附近时，展开方向自动改为向上，按钮不会被屏幕裁掉。</p><h2 id="关闭与恢复" tabindex="-1">关闭与恢复 <a class="header-anchor" href="#关闭与恢复" aria-label="Permalink to &quot;关闭与恢复&quot;">​</a></h2><p>点悬浮条左上角的 ×，三个选项按需选：</p><table tabindex="0"><thead><tr><th>选项</th><th>生效范围</th><th>恢复位置</th></tr></thead><tbody><tr><td>本次不显示</td><td>关闭这个标签页前不再显示</td><td>新开标签页自动恢复</td></tr><tr><td>在 {host} 不显示</td><td>只在当前网站不显示</td><td>弹窗「功能」页 →「悬浮快捷栏」</td></tr><tr><td>全部网站都不显示</td><td>所有网站</td><td>设置页「网页增强」→「显示悬浮快捷栏」</td></tr></tbody></table><p>弹窗「功能」页的开关同样可以按网站开 / 关；设置页「网页增强」里还有总开关和「不显示的网站」列表。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>只在网页最外层显示：网页里嵌的 iframe 不显示，看视频全屏时自动隐藏</li><li>系统开了深色模式时，悬浮栏自动切换配色</li></ul><img src="'+i+'" alt="深色主题">',16)])])}const f=r(l,[["render",h]]);export{m as __pageData,f as default};
